// Game PID for given IVs: every PID found, generated by the game from its origin, gives the same IVs.
import { expect, test } from "vitest";
import { STATS } from "../src/lib/gen3/pk3";
import { staticSpread } from "../src/lib/gen3/rng";
import { pidIvMethod, pidsForIvs } from "../src/lib/gen3/pidiv";

test("each PID found comes out of the game with the requested IVs, in the reported method", () => {
  const ivs = { hp: 31, attack: 31, defense: 20, speed: 31, sp_attack: 5, sp_defense: 25 };
  const found = pidsForIvs(ivs);
  expect(found.length).toBeGreaterThan(0);
  for (const f of found) {
    const spread = staticSpread(f.origin, f.method);
    expect(spread.pid).toBe(f.pid);
    expect(STATS.map((k) => spread.ivs[k])).toEqual(STATS.map((k) => ivs[k]));
  }
});

test("finds the PID of a Pokémon generated by the game", () => {
  for (const [origin, method] of [[0x12345678, 1], [0xdeadbeef, 2], [0x0badf00d, 4]] as const) {
    const made = staticSpread(origin, method);
    const found = pidsForIvs(made.ivs);
    expect(found.some((f) => f.pid === made.pid && f.method === method && f.origin === origin)).toBe(true);
  }
});

test("pidIvMethod confirms the PIDs pidsForIvs finds and rejects an arbitrary one", () => {
  const ivs = { hp: 31, attack: 0, defense: 31, speed: 31, sp_attack: 31, sp_defense: 31 };
  const found = pidsForIvs(ivs).slice(0, 6);
  for (const { pid } of found) expect(pidIvMethod(pid, ivs)).not.toBeNull();
  expect(pidIvMethod(0x12345678, ivs)).toBeNull();
});
